('biology',1,'الخلية','Cell discovery and Cell Theory','ar','نظرية الخلية تعتمد أساساً على عمل أي عالمين؟','["\u0631\u0648\u0628\u0631\u062a \u0647\u0648\u0643 \u0648\u0631\u0648\u0628\u0631\u062a \u0628\u0631\u0627\u0648\u0646", "\u0623\u0646\u062a\u0648\u0627\u0646 \u0641\u0627\u0646 \u0644\u064a\u0641\u0646\u0647\u0648\u0643 \u0648\u0631\u0648\u0628\u0631\u062a \u0647\u0648\u0643", "\u0645\u0627\u062a\u064a\u0627\u0633 \u0634\u0644\u0627\u064a\u062f\u0646 \u0648\u062b\u064a\u0648\u062f\u0648\u0631 \u0634\u0648\u0627\u0646", "\u062b\u064a\u0648\u062f\u0648\u0631 \u0634\u0648\u0627\u0646 \u0648\u0631\u0648\u0628\u0631\u062a \u0628\u0631\u0627\u0648\u0646"]'::jsonb,2,'Ministerial-style bank',302),
