('biology',1,'الخلية','Prokaryotic cell','ar','يحاط جدار الخلية في الطحالب الخضر المزرقة بـ:','["\u0645\u062d\u0641\u0638\u0629", "\u063a\u0634\u0627\u0621 \u062c\u064a\u0644\u0627\u062a\u064a\u0646\u064a", "\u0637\u0628\u0642\u0629 \u0643\u064a\u062a\u064a\u0646\u064a\u0629", "\u0637\u0628\u0642\u0629 \u0645\u0632\u062f\u0648\u062c\u0629 \u0645\u0646 \u0627\u0644\u062f\u0647\u0648\u0646 \u0627\u0644\u0645\u0641\u0633\u0641\u0631\u0629"]'::jsonb,1,'Ministerial-style bank',305),
