('biology',1,'الخلية','Endoplasmic Reticulum','ar','تكثر الشبكة البلازمية الداخلية الملساء في خلايا المبايض والخصى والغدد الكظرية لأنها تفرز:','["\u0625\u0646\u0632\u064a\u0645\u0627\u062a \u0647\u0636\u0645\u064a\u0629", "\u0633\u0643\u0631\u064a\u0627\u062a \u0645\u0639\u0642\u062f\u0629", "\u0647\u0631\u0645\u0648\u0646\u0627\u062a \u0633\u062a\u064a\u0631\u0648\u064a\u062f\u064a\u0629", "\u0625\u0646\u0632\u064a\u0645\u0627\u062a \u062a\u0646\u0641\u0633\u064a\u0629"]'::jsonb,2,'Ministerial-style bank',313),
