('biology',1,'الخلية','Cell division','ar','في انقسام الخلية النباتية، يحدث انقسام السايتوبلازم من خلال تكوين:','["\u0623\u062e\u062f\u0648\u062f \u0627\u0646\u0642\u0633\u0627\u0645 \u064a\u0646\u062d\u0646\u064a \u0644\u0644\u062f\u0627\u062e\u0644", "\u062d\u0644\u0642\u0629 \u0627\u0646\u0642\u0628\u0627\u0636\u064a\u0629", "\u0635\u0641\u064a\u062d\u0629 \u062e\u0644\u0648\u064a\u0629 \u062a\u0646\u0645\u0648 \u0645\u0646 \u0627\u0644\u0645\u0631\u0643\u0632 \u0625\u0644\u0649 \u0627\u0644\u062e\u0627\u0631\u062c", "\u062c\u064a\u0628 \u0628\u0644\u0639\u0645\u064a"]'::jsonb,2,'Ministerial-style bank',349);